//! Mandelbrot escape times computed by a GPU compute kernel (wgpu),
//! summarized on the host.

use std::process::exit;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    let j = gid.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    out[j * params.width + i] = n;
}
"#;

struct Input {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let first: Vec<&str> = lines
        .next()
        .ok_or("missing first line")?
        .split_whitespace()
        .collect();
    let second: Vec<&str> = lines
        .next()
        .ok_or("missing second line")?
        .split_whitespace()
        .collect();
    if first.len() != 3 || second.len() != 4 {
        return Err("expected 3 numbers on line 1 and 4 on line 2".into());
    }
    let int = |s: &str, lo: u32, hi: u32| -> Result<u32, String> {
        let v: u32 = s.parse().map_err(|e| format!("bad integer {s:?}: {e}"))?;
        if v < lo || v > hi {
            return Err(format!("{v} out of range {lo}..={hi}"));
        }
        Ok(v)
    };
    let float = |s: &str| -> Result<f64, String> {
        let v: f64 = s.parse().map_err(|e| format!("bad number {s:?}: {e}"))?;
        if !v.is_finite() {
            return Err(format!("non-finite number {s:?}"));
        }
        Ok(v)
    };
    let input = Input {
        width: int(first[0], 1, 1024)?,
        height: int(first[1], 1, 1024)?,
        limit: int(first[2], 1, 1000)?,
        x_min: float(second[0])?,
        x_max: float(second[1])?,
        y_min: float(second[2])?,
        y_max: float(second[3])?,
    };
    if input.x_min >= input.x_max || input.y_min >= input.y_max {
        return Err("bounds must satisfy x_min < x_max and y_min < y_max".into());
    }
    Ok(input)
}

/// Point coordinates along one axis, computed in double precision.
fn axis(min: f64, max: f64, count: u32) -> Vec<f32> {
    let step = (max - min) / f64::from(count);
    (0..count)
        .map(|k| (min + (f64::from(k) + 0.5) * step) as f32)
        .collect()
}

fn escape_times_gpu(input: &Input) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: None,
        required_limits: wgpu::Limits::downlevel_defaults(),
        ..Default::default()
    }))
    .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let xs = axis(input.x_min, input.x_max, input.width);
    let ys = axis(input.y_min, input.y_max, input.height);
    let params = [input.width, input.height, input.limit, 0u32];
    let count = (input.width as usize) * (input.height as usize);
    let size = (count * std::mem::size_of::<u32>()) as wgpu::BufferAddress;

    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let xs_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("xs"),
        contents: bytemuck::cast_slice(&xs),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let ys_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("ys"),
        contents: bytemuck::cast_slice(&ys),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let out_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("out"),
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let read_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("escape"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("escape"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: xs_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: ys_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: out_buf.as_entire_binding(),
            },
        ],
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(input.width.div_ceil(8), input.height.div_ceil(8), 1);
    }
    encoder.copy_buffer_to_buffer(&out_buf, 0, &read_buf, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = read_buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback lost: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;
    let data = slice.get_mapped_range();
    let times: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    read_buf.unmap();
    Ok(times)
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: escape <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse_input(&text)?;
    let times = escape_times_gpu(&input)?;

    let limit = input.limit;
    let mut inside: u64 = 0;
    let mut bins = [0u64; 8];
    let mut sum: u64 = 0;
    let mut escaped: u64 = 0;
    for &n in &times {
        if n >= limit {
            inside += 1;
        } else {
            bins[(8 * n / limit) as usize] += 1;
            sum += u64::from(n);
            escaped += 1;
        }
    }
    let mean = if escaped == 0 {
        0.0
    } else {
        sum as f64 / escaped as f64
    };

    let mut out = format!("INSIDE {inside}\n");
    for (k, c) in bins.iter().enumerate() {
        out.push_str(&format!("BIN {k} {c}\n"));
    }
    out.push_str(&format!("MEAN {mean:.3}\n"));
    print!("{out}");
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        exit(1);
    }
}

